  print(name, (uu,vv), 'd',round(float(d[vv,uu]),4),'xyz',np.round(world(uu,vv),4))
 print()
# Stats world coordinates for ground plane samples
coords=[]
for v in range(300,445,15):
 for u in range(100,780,20):
  z=float(d[v,u]); p=world(u,v)
  if z<5 and p[2]>.72 and p[2]<.9: coords.append(p)
print('likely table z mean/std',np.mean(np.array(coords),axis=0),np.std(np.array(coords),axis=0),len(coords))
